import requests
name='(4-nitrophenyl) N-[(1S,9S,10S,15R,16R,17S)-12-ethoxyimino-4-[(2-fluorophenyl)methoxy]-15,16-bis(4-hydroxybutyl)-9-prop-2-enoxy-8-oxatetracyclo[7.7.1.02,7.013,17]heptadeca-2(7),3,5,13-tetraen-10-yl]-N-(naphthalen-1-ylmethyl)carbamate'
for url in ['https://opsin.ch.cam.ac.uk/opsin/'+requests.utils.quote(name,safe='')+'.json','https://cactus.nci.nih.gov/chemical/structure/'+requests.utils.quote(name,safe='')+'/smiles']:
 try:
  r=requests.get(url,timeout=20); print(url, r.status_code, r.text[:1000])
 except Exception as e: print(type(e).__name__,e)
